'use strict';
// Global LOLA grid is for regional exploration, never landing certification.
let globalDem=null,demLoadError=false;
const elevationStops=[[0,[77,64,149]],[.25,[51,137,205]],[.5,[107,203,194]],[.65,[241,213,101]],[.82,[231,126,66]],[1,[176,37,65]]];
function elevationRGB(m){const t=Math.max(0,Math.min(1,(m+9000)/20000));for(let i=1;i<elevationStops.length;i++){const [v,c]=elevationStops[i],[u,b]=elevationStops[i-1];if(t<=v)return c.map((x,k)=>Math.round(b[k]+(x-b[k])*(t-u)/(v-u)));}return elevationStops.at(-1)[1];}
function demCell(lon,lat){const w=1440,h=720,x=((Math.floor((lon+180)*4)%w)+w)%w,y=Math.max(0,Math.min(h-1,Math.floor((90-lat)*4))),z=globalDem[y*w+x];if(Math.abs(lat)>85)return {z,slope:null};const dx=1737400*Math.PI/720*Math.cos(lat*Math.PI/180),dy=1737400*Math.PI/720,gx=(globalDem[y*w+(x+1)%w]-globalDem[y*w+(x+w-1)%w])/(2*dx),gy=(globalDem[(y+1)*w+x]-globalDem[(y-1)*w+x])/(2*dy);return{z,slope:Math.atan(Math.hypot(gx,gy))*180/Math.PI};}
function terrainExplorerMarkup(){return `<section class="terrain-explorer"><div class="panelhead"><div><span class="eyebrow">LA LUNA EN COLORES</span><h2>Conocé el terreno antes de elegir</h2></div><span class="pill">NASA · LOLA</span></div><div class="terrain-explorer-grid"><div><canvas width="460" height="400" tabindex="0" role="img" aria-label="Luna con elevaciones LOLA. Arrastrar para rotar; flechas del teclado para girar."></canvas><div class="terrain-rotations"><button data-pose="near">Cara visible</button><button data-pose="far">Cara oculta</button><button data-pose="south">Polo sur</button></div><small>Arrastrá para girar · flechas con foco en el globo</small></div><div class="terrain-explainer"><label>Capa del globo<select data-dem-layer><option value="altitude">Altitud · altura del terreno</option><option value="gentle">Pendiente regional · verde = menor inclinación</option></select></label><label>Límite de pendiente regional: <b data-dem-limit-label>10°</b><input data-dem-limit type="range" min="1" max="20" value="10"></label><div data-dem-legend></div><p data-dem-readout role="status">Cargando elevaciones NASA…</p><p class="game-small">El punto blanco del centro indica la muestra leída. Los colores de altitud no califican un sitio como ideal.</p><div class="terrain-caution">Verde = cumple el límite de pendiente a esta escala. Para alunizar también importan rocas, rugosidad, luz y comunicaciones.</div><p class="game-small">Malla global de 0,25° (≈7,6 km norte-sur). No resuelve un área de alunizaje. En la capa de pendientes, los polos >85° quedan grises por limitación de esta estimación.</p><a href="https://svs.gsfc.nasa.gov/4720/" target="_blank" rel="noopener">Fuente y referencia de alturas · NASA SVS ↗</a></div></div></section>`;}
function mountTerrainExplorers(){document.querySelectorAll('.terrain-explorer:not([data-mounted])').forEach(box=>{box.dataset.mounted='true';const c=box.querySelector('canvas'),ctx=c.getContext('2d');let lon=0,lat=0,dragging=null;const layer=box.querySelector('[data-dem-layer]'),limit=box.querySelector('[data-dem-limit]'),read=box.querySelector('[data-dem-readout]');function draw(){const lim=+limit.value;box.querySelector('[data-dem-limit-label]').textContent=lim+'°';box.querySelector('[data-dem-legend]').innerHTML=layer.value==='altitude'?'<div class="altitude-ramp"></div><div class="dem-scale"><span>−9 km</span><span>0</span><span>+11 km</span></div><small>Altitud respecto a un radio lunar de 1.737,4 km.</small>':`<div class="terrain-key"><span>🟢 ≤ ${lim}° · menor pendiente</span><span>🟠 Hasta ${Math.min(90,lim*1.5).toFixed(1)}° · precaución</span><span>🔴 Mayor pendiente</span><span>⬜ Polos sin estimación</span></div>`;ctx.clearRect(0,0,460,400);if(!globalDem){read.textContent=demLoadError?'No se pudo cargar el DEM; recargá la página.':'Cargando elevaciones NASA…';return;}const out=ctx.createImageData(460,400),r=175,cp=Math.cos(lat),sp=Math.sin(lat),cr=Math.cos(lon),sr=Math.sin(lon);for(let y=20;y<380;y++)for(let x=50;x<410;x++){const vx=(x-230)/r,vy=-(y-200)/r,rr=vx*vx+vy*vy;if(rr>1)continue;const vz=Math.sqrt(1-rr),yy=vy*cp+vz*sp,zz=-vy*sp+vz*cp,xx=vx*cr+zz*sr,zzz=-vx*sr+zz*cr,lo=Math.atan2(xx,zzz)*180/Math.PI,la=Math.asin(Math.max(-1,Math.min(1,yy)))*180/Math.PI,d=demCell(lo,la);const col=layer.value==='altitude'?elevationRGB(d.z):d.slope===null?[118,126,142]:d.slope<=lim?[63,207,143]:d.slope<=lim*1.5?[245,184,65]:[232,89,96],i=(y*460+x)*4,shade=.55+.45*vz;for(let k=0;k<3;k++)out.data[i+k]=col[k]*shade;out.data[i+3]=255;}ctx.putImageData(out,0,0);ctx.strokeStyle='#ffffff';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(230,200,4,0,Math.PI*2);ctx.stroke();const lo=((lon*180/Math.PI+180)%360+360)%360-180,la=lat*180/Math.PI,d=demCell(lo,la);read.textContent=`Centro: ${la.toFixed(2)}° lat · ${lo.toFixed(2)}° lon · ${d.z.toLocaleString('es-AR')} m · pendiente regional ${d.slope===null?'no estimada':d.slope.toFixed(1)+'°'}`;}
box.redrawDem=draw;layer.onchange=draw;limit.oninput=draw;c.onpointerdown=e=>{dragging={x:e.clientX,y:e.clientY};c.setPointerCapture(e.pointerId);};c.onpointermove=e=>{if(!dragging)return;lon-=(e.clientX-dragging.x)*.008;lat=Math.max(-Math.PI/2,Math.min(Math.PI/2,lat+(e.clientY-dragging.y)*.008));dragging={x:e.clientX,y:e.clientY};draw();};c.onpointerup=c.onpointercancel=()=>dragging=null;c.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();lon+=e.key==='ArrowRight'?.12:e.key==='ArrowLeft'?-.12:0;lat=Math.max(-Math.PI/2,Math.min(Math.PI/2,lat+(e.key==='ArrowUp'?.12:e.key==='ArrowDown'?-.12:0)));draw();};box.querySelectorAll('[data-pose]').forEach(b=>b.onclick=()=>{lon=b.dataset.pose==='far'?Math.PI:0;lat=b.dataset.pose==='south'?-Math.PI/2:0;draw();});draw();});}
$('globalTerrain').innerHTML=terrainExplorerMarkup();mountTerrainExplorers();
fetch('assets/lola-global-meters.bin').then(r=>{if(!r.ok)throw Error('DEM');return r.arrayBuffer();}).then(b=>{if(b.byteLength!==1440*720*2)throw Error('DEM size');const v=new DataView(b);globalDem=new Int16Array(1440*720);for(let i=0;i<globalDem.length;i++)globalDem[i]=v.getInt16(i*2,true);document.querySelectorAll('.terrain-explorer').forEach(x=>x.redrawDem?.());}).catch(()=>{demLoadError=true;document.querySelectorAll('.terrain-explorer').forEach(x=>x.redrawDem?.());});
const originalSlopeDraw=drawSlope;
drawSlope=function(){originalSlopeDraw();const mode=$('localTerrainLayer').value,lim=+$('slopeLimit').value,ctx=$('slopeMap').getContext('2d');if(mode==='slope')return;let accepted=0;for(let j=0;j<200;j++)for(let i=0;i<200;i++){const z=terrain(i*5,j*5),a=slopes[j*200+i],ok=a<=lim;accepted+=ok;const rgb=mode==='filtered'?(ok?elevationRGB((z+100)*90-9000):[112,119,132]):ok?[61,205,140]:a<=lim*1.5?[245,184,65]:[224,83,96];ctx.fillStyle=`rgb(${rgb.join(',')})`;ctx.fillRect(i*3,j*2,3,2);}ctx.fillStyle='#fff';ctx.font='13px Segoe UI';ctx.fillText('DEMO LOCAL · 1 × 1 km',12,25);$('localTerrainLegend').textContent=mode==='filtered'?'Altitud sintética: violeta = menor, rojo = mayor; gris = pendiente por encima del límite.':'Verde = pendiente bajo el límite; naranja = hasta 1,5 × límite; rojo = mayor pendiente. Solo criterio de inclinación.';};
const slopeLimitBase=updateSlopeLimit;updateSlopeLimit=function(){slopeLimitBase();};$('slopeLimit').oninput=()=>drawSlope();$('localTerrainLayer').onchange=()=>{$('localTerrainLegend').textContent=$('localTerrainLayer').value==='slope'?'Escala continua de pendiente: 0° a 45° o más.':'';drawSlope();};drawSlope();
